'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelClient} from '@/lib/pilot';
import {readRevenueDemandAdjustmentSet,type RevenueDemandAdjustment} from '@/lib/revenue-demand-adjustments';

type SaveCommand={request:string;expectedVersion:number;adjustments:RevenueDemandAdjustment[]};
const asBasisPoints=(value:string)=>{if(!/^-?(?:0|[1-9]\d{0,2})(?:\.\d{1,2})?$/.test(value))throw Error('Enter an adjustment from -50.00% to 100.00%.');const scaled=Number(value)*100;if(!Number.isSafeInteger(Math.round(scaled))||scaled<-5000||scaled>10000)throw Error('Enter an adjustment from -50.00% to 100.00%.');return Math.round(scaled)};
const hasControls=(value:string)=>{for(let i=0;i<value.length;i++){const code=value.charCodeAt(i);if(code<32||code===127)return true}return false};
const sameInputs=(left:RevenueDemandAdjustment[],right:RevenueDemandAdjustment[])=>JSON.stringify([...left].sort((a,b)=>a.id.localeCompare(b.id)))===JSON.stringify([...right].sort((a,b)=>a.id.localeCompare(b.id)));

export function RevenueDemandCalendar({actor,tenant,property,businessDate}:{actor:string;tenant:string;property:string;businessDate:string}){
 const [open,setOpen]=useState(false),[loaded,setLoaded]=useState(false),[loading,setLoading]=useState(false),[busy,setBusy]=useState(false),[uncertain,setUncertain]=useState(false),[version,setVersion]=useState(0),[saved,setSaved]=useState<RevenueDemandAdjustment[]>([]),[draft,setDraft]=useState<RevenueDemandAdjustment[]>([]),[kind,setKind]=useState<'event'|'seasonality'>('event'),[label,setLabel]=useState(''),[start,setStart]=useState(businessDate),[end,setEnd]=useState(businessDate),[percent,setPercent]=useState('0'),[error,setError]=useState(''),[notice,setNotice]=useState('');
 const pending=useRef<SaveCommand|null>(null),mounted=useRef(false),controller=useRef<AbortController|null>(null),saving=useRef(false);
 const load=useCallback(async()=>{
  controller.current?.abort();const abort=new AbortController();controller.current=abort;const timer=window.setTimeout(()=>abort.abort(),15000);setLoading(true);setError('');
  try{const client=hotelClient(),auth=await client.auth.getUser();if(auth.error||auth.data.user?.id!==actor)throw Error('Sign in again before reviewing demand planning.');const response=await client.rpc('irp_pms_pilot_revenue_demand_adjustments',{p_tenant:tenant,p_property:property}).abortSignal(abort.signal);if(response.error)throw Error(response.error.code==='PGRST202'?'Event and seasonality inputs are not activated in the connected hotel database yet.':response.error.code==='42501'?'Your account cannot read these property settings.':response.error.message);const result=readRevenueDemandAdjustmentSet(response.data,{tenant,property});if(!mounted.current||abort.signal.aborted)return;setVersion(result.version);setSaved(result.adjustments);setDraft(result.adjustments);setLoaded(true);const command=pending.current;if(command){const statusResponse=await client.rpc('irp_pms_pilot_revenue_demand_adjustment_status',{p_tenant:tenant,p_property:property,p_request:command.request}).abortSignal(abort.signal);if(statusResponse.error)throw Error(statusResponse.error.message);const status=statusResponse.data as Record<string,unknown>;if(status?.found===true){const savedRequest=readRevenueDemandAdjustmentSet({tenant_id:status.tenant_id,property_id:status.property_id,version:status.version,adjustments:status.adjustments,saved_at:status.saved_at},{tenant,property});if(status.expected_version!==command.expectedVersion||!sameInputs(savedRequest.adjustments,command.adjustments))throw Error('The previous request receipt did not match the exact saved input. Keep it for owner review.');pending.current=null;setUncertain(false);setNotice('The previous save is confirmed in the property history.');}else setNotice('The previous save has not been confirmed. Retry the exact save to finish it safely.');}else setNotice('');}
  catch(reason){if(!mounted.current||abort.signal.aborted)return;setLoaded(false);setError(reason instanceof Error?reason.message:'Demand planning inputs could not be loaded.');}
  finally{window.clearTimeout(timer);if(controller.current===abort)controller.current=null;if(mounted.current)setLoading(false);}
 },[actor,tenant,property]);
 useEffect(()=>{mounted.current=true;if(!open)return()=>{mounted.current=false;controller.current?.abort()};const timer=window.setTimeout(()=>void load(),0);return()=>{window.clearTimeout(timer);mounted.current=false;controller.current?.abort()}},[open,load]);
 const add=(event:{preventDefault:()=>void})=>{event.preventDefault();setError('');try{const clean=label.trim();if(!clean||clean.length>120||hasControls(clean))throw Error('Enter a short label without control characters.');if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||start>end||Date.parse(`${end}T00:00:00Z`)-Date.parse(`${start}T00:00:00Z`)>366*86_400_000)throw Error('Choose a valid date range of 366 days or less.');const basis=asBasisPoints(percent);const existing=draft.filter(item=>item.kind===kind).length;if(existing>=(kind==='event'?25:12))throw Error(kind==='event'?'A property can save up to 25 events.':'A property can save up to 12 seasonal periods.');setDraft(current=>[...current,{id:crypto.randomUUID(),kind,label:clean,startDate:start,endDate:end,adjustmentBasisPoints:basis}].sort((a,b)=>a.startDate.localeCompare(b.startDate)||a.kind.localeCompare(b.kind)||a.label.localeCompare(b.label)));setLabel('');setPercent('0');setNotice('Unsaved input added. Save the property calendar to keep it.');}catch(reason){setError(reason instanceof Error?reason.message:'Could not add the demand input.');}};
 const save=async()=>{if(saving.current||!loaded)return;saving.current=true;setBusy(true);setError('');setNotice('');let dispatched=false;try{const auth=await hotelClient().auth.getUser();if(auth.error||auth.data.user?.id!==actor)throw Error('Sign in again before saving.');const command=pending.current??{request:crypto.randomUUID(),expectedVersion:version,adjustments:structuredClone(draft)};pending.current=command;setUncertain(true);const request=hotelClient().rpc('irp_pms_pilot_save_revenue_demand_adjustments',{p_tenant:tenant,p_property:property,p_request:command.request,p_expected_version:command.expectedVersion,p_adjustments:command.adjustments}).abortSignal(AbortSignal.timeout(15000));dispatched=true;const response=await request;if(response.error){if(['22023','23505','40001','42501'].includes(response.error.code??'')){pending.current=null;setUncertain(false);}throw Error(response.error.code==='PGRST202'?'Event and seasonality inputs are not activated in the connected hotel database yet.':response.error.code==='40001'?'Another manager changed these settings. Refresh, review the latest list and add your changes again.':response.error.code==='42501'?'Only an owner or manager can save these settings.':response.error.message);}const receipt=response.data as Record<string,unknown>;if(!receipt||receipt.tenant_id!==tenant||receipt.property_id!==property||receipt.version!==command.expectedVersion+1||receipt.count!==command.adjustments.length||typeof receipt.replayed!=='boolean')throw Error('The saved settings receipt could not be verified. Retry the same save or refresh the saved settings.');pending.current=null;setUncertain(false);await load();setNotice('Event and seasonality inputs saved for this property. They do not change rates automatically.');}
  catch(reason){if(!dispatched){pending.current=null;setUncertain(false);}if(mounted.current)setError(reason instanceof Error?reason.message:'The save result is unknown. Retry the exact save or refresh before editing.');}
  finally{saving.current=false;if(mounted.current)setBusy(false);}
 };
 const changed=JSON.stringify(saved)!==JSON.stringify(draft);
 return <section className="card revenue-demand-calendar" aria-labelledby="revenue-demand-calendar-title"><div className="section-top"><div><h2 id="revenue-demand-calendar-title">Events &amp; seasonal demand inputs</h2><p>Save property-specific demand context for forecasting. These inputs never change rates automatically.</p></div><button type="button" className="secondary" aria-expanded={open} onClick={()=>setOpen(value=>!value)}>{open?'Hide calendar':'Manage calendar'}</button></div>
 {open&&<><div className="section-top"><span>{loaded?`${saved.length} saved inputs · version ${version}`:'Load the saved property calendar before editing.'}</span><button type="button" className="secondary" disabled={loading||busy} onClick={()=>void load()}>{loading?'Loading…':'Refresh saved settings'}</button></div>
 {uncertain&&<output>The last save result may be unknown. Retry keeps the same request and input snapshot.</output>}
 <form className="revenue-demand-form" onSubmit={add}><label className="field">Input type<select value={kind} disabled={busy||uncertain} onChange={event=>setKind(event.target.value as 'event'|'seasonality')}><option value="event">Local event</option><option value="seasonality">Seasonal period</option></select></label><label className="field">Name<input value={label} onChange={event=>setLabel(event.target.value)} maxLength={120} required disabled={!loaded||busy||uncertain} placeholder={kind==='event'?'Convention, festival, tournament':'Summer peak, shoulder season'}/></label><label className="field">Demand adjustment (%)<input type="number" step="0.01" min="-50" max="100" value={percent} onChange={event=>setPercent(event.target.value)} required disabled={!loaded||busy||uncertain}/></label><div className="form-grid"><label className="field">Starts<input type="date" value={start} onChange={event=>setStart(event.target.value)} disabled={!loaded||busy||uncertain}/></label><label className="field">Ends<input type="date" value={end} onChange={event=>setEnd(event.target.value)} disabled={!loaded||busy||uncertain}/></label></div><button className="secondary" disabled={!loaded||busy||uncertain}>Add input</button></form>
 <div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Type</th><th>Name</th><th>Dates</th><th>Adjustment</th><th>Action</th></tr></thead><tbody>{draft.map(item=><tr key={item.id}><td>{item.kind==='event'?'Event':'Seasonality'}</td><td>{item.label}</td><td>{item.startDate} – {item.endDate}</td><td>{item.adjustmentBasisPoints>=0?'+':''}{(item.adjustmentBasisPoints/100).toFixed(2)}%</td><td><button type="button" className="text-button" disabled={busy||uncertain} onClick={()=>setDraft(current=>current.filter(row=>row.id!==item.id))}>Remove</button></td></tr>)}{!draft.length&&<tr><td colSpan={5}>No demand inputs saved.</td></tr>}</tbody></table></div>
 <div className="manager-brief-save"><button type="button" className="primary" disabled={!loaded||busy||(!uncertain&&!changed)} onClick={()=>void save()}>{busy?'Saving…':uncertain?'Retry same save':'Save demand inputs'}</button><span>Each save is versioned and property-scoped. Maximum 25 events and 12 seasonal periods.</span></div>
 {error&&<p className="pilot-error" role="alert">{error}</p>}{notice&&<output className="manager-brief-success">{notice}</output>}
 <p className="muted">Managers enter these adjustments manually. External calendars and market demand feeds are not connected. Saved settings are not yet applied by the PMS demand forecast.</p></>}
 </section>;
}
